 // Enable Include BuildContext only if your host presentation requires it.
 // Add this import below FlutterFlow's autogenerated imports:
 // import 'package:aya_flutter/aya_flutter.dart';
 //
 // Register an async action named ayaFlutterFlowOpenHelp that accepts:
 // question (String, optional or default ""), screenName (String, optional).
 // Return type: String. Treat it as a LOCAL UI status only.

Future<String> ayaFlutterFlowOpenHelp(
  String question,
  String? screenName,
) async {
  final local = await AyaFlutter.openHelp(
    question: question,
    screenName: screenName?.trim().isEmpty == true ? null : screenName,
    askQuestion: false, // The host already collected the question.
  );
  switch (local.status) {
    case AyaLocalStatus.questionOpened:
      return 'question_opened';
    case AyaLocalStatus.reviewOpened:
      return 'review_opened';
    case AyaLocalStatus.rejected:
      return 'rejected';
  }
}
